import assert from'node:assert/strict';import type{Question}from'../../src/core/types';import{bindBodyAnswers}from'../../src/core/generators/definition';import{legacy2019RankingDefinitions,legacy2019RankingProfiles}from'../../src/core/generators/legacy-2019-pm-ranking';import{legacy2019AttributedFigureBlocks}from'./legacy-2019-spring-local-diagram-attribution';import{legacy2019CandidateSchema}from'./legacy-2019-spring-local-diagnostic';
export function legacy2019RankingSchema(q:Question){assert.equal(q.learning?.area,'technology');if(q.origin.kind!=='official_reprint'){const figures=q.prompt.blocks.filter(b=>b.type==='diagram');assert.equal(figures.length,5);figures.forEach((f,i)=>{assert.equal(f.scene.kind,'source_figure');if(f.scene.kind!=='source_figure')throw Error('Unexpected diagram');assert.equal(f.scene.profile,legacy2019RankingProfiles[i]);assert.equal(f.scene.values.length,1);assert([1,2].includes(i)?f.scene.values[0]===0||f.scene.values[0]===1:f.scene.values[0]===0);});assert(q.choices.every(c=>!c.content.blocks.some(b=>b.type==='diagram')));}return legacy2019CandidateSchema(q);}
export function bindLegacy2019Ranking(base:Question,values:number[]):Question{assert.equal(base.id,'question-template-source-2019h31h-fe-pm-10');assert.equal(base.prompt.attribution.origin,'adapted');assert.deepEqual(base.contexts,[]);assert.deepEqual(base.contextRefs,[]);assert.deepEqual(base.assetRefs,[]);const body=legacy2019RankingDefinitions[0].build(values),q=structuredClone(base);q.prompt.blocks=legacy2019AttributedFigureBlocks(body.prompt,base.prompt.attribution);q.choices=body.choices.map((blocks,i)=>({id:'choice-value-'+(i+1),content:{attribution:structuredClone(base.prompt.attribution),blocks:legacy2019AttributedFigureBlocks(blocks,base.prompt.attribution)}}));bindBodyAnswers(q,body,q.correctAnswer.attribution);q.explanation.blocks=[{type:'paragraph',text:body.explanation}];return q;}
